-- Núcleo agronómico de enfermedades de soja v2.0.
-- Fuente primaria: patogenos_soja_condiciones_ambientales 14-08.xlsx (Natali).
-- La migración conserva el historial y retira la regla foliar genérica para evitar doble señal.

create table if not exists catalogo_enfermedades (
  id uuid primary key default gen_random_uuid(),
  cultivo text not null,
  clave text not null,
  categoria text not null,
  nombre text not null,
  nombre_cientifico text,
  organo_afectado text not null,
  evaluabilidad text not null check (evaluabilidad in ('EVALUABLE','PARCIALMENTE_EVALUABLE','NO_EVALUABLE','PENDIENTE_EVIDENCIA')),
  modo_avizor text check (modo_avizor in ('ESTABLE','EXPERIMENTAL')),
  estado_catalogo text not null check (estado_catalogo in ('activa','catalogada','retirada')),
  condiciones_normalizadas jsonb not null,
  factores_no_observables text[] not null default '{}',
  cobertura_esperada text not null check (cobertura_esperada in ('COMPLETA','PARCIAL','INSUFICIENTE')),
  fuentes jsonb not null,
  version text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (cultivo, clave, version),
  check (jsonb_typeof(condiciones_normalizadas) = 'object'),
  check (jsonb_typeof(fuentes) = 'array')
);

-- El índice legacy impedía varias reglas específicas dentro de una misma categoría.
-- La identidad v2 sigue protegida por reglas_agronomicas_clave_version_idx.
drop index if exists reglas_agronomicas_unique_rule_idx;

insert into catalogo_enfermedades
