on conflict (cultivo,clave,version) do update set
  evaluabilidad=excluded.evaluabilidad, estado_catalogo=excluded.estado_catalogo,
  condiciones_normalizadas=excluded.condiciones_normalizadas, factores_no_observables=excluded.factores_no_observables,
  cobertura_esperada=excluded.cobertura_esperada, fuentes=excluded.fuentes, updated_at=now();

update catalogo_enfermedades set modo_avizor = case
  when clave in ('cercospora_kikuchii','roya_asiatica','macrophomina','oidio','mildiu') then 'ESTABLE'
  when clave in ('antracnosis','sclerotinia','mancha_ojo_rana','tizon_bacteriano','pustula_bacteriana') then 'EXPERIMENTAL'
  else null
end
where cultivo='soja' and version='2.0';

-- Evita evaluar simultáneamente la señal genérica anterior y las específicas y deja auditoría.
with anteriores as (
  select id, to_jsonb(reglas_agronomicas.*) as valor_anterior
  from reglas_agronomicas where cultivo='soja' and clave='enfermedades_foliares' and estado <> 'retirada'
), retiradas as (
  update reglas_agronomicas r set estado='retirada', activa=false, updated_at=now()
  from anteriores a where r.id=a.id returning r.id, a.valor_anterior, to_jsonb(r.*) as valor_nuevo
)
insert into auditoria(actor_id,actor_tipo,accion,entidad,entidad_id,valor_anterior,valor_nuevo,request_id)
select 'migration-009','service','retirar_version','regla',id::text,valor_anterior,valor_nuevo,gen_random_uuid() from retiradas;

with nuevas(clave,categoria,ventana,fuente,limitaciones,definicion) as (values
('antracnosis','fin_ciclo',5,'Natali 14-08; INTA','Evaluación parcial: sin mojado foliar observado, rastrojo ni inóculo.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con antracnosis","explicacion":"Coinciden temperatura y humedad; no constituye diagnóstico.","recomendacion":"Monitorear vainas, tallos y pecíolos.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[25,30],"unidad":"C"},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"gte","valor":85,"unidad":"%"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('cercospora_kikuchii','fin_ciclo',5,'Natali 14-08; INTA','Evaluación parcial: no observa rastrojo, semilla infectada ni inóculo.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con tizón por Cercospora","explicacion":"Coinciden temperatura y humedad persistente; no constituye diagnóstico.","recomendacion":"Monitorear el lote, especialmente en etapas reproductivas.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[23,28],"unidad":"C"},{"variable":"humedad_relativa","agregador":"dias_con_condicion","operador":"gte","valor":4,"unidad":"dias","subcondicion":{"operador":"gte","valor":85,"unidad":"%"}}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('roya_asiatica','foliar',5,'Natali 14-08; SINAVIMO/SENASA','Evaluación parcial: no mide 6 h de mojado/rocío ni presencia de inóculo. HR >75% es el umbral favorable primario.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con roya asiática","explicacion":"Coinciden temperatura, humedad y precipitación reciente; no constituye diagnóstico.","recomendacion":"Intensificar el monitoreo del lote.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[14,28],"unidad":"C"},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"gt","valor":75,"unidad":"%"},{"variable":"precipitacion","agregador":"dias_con_condicion","operador":"gte","valor":1,"unidad":"dias","subcondicion":{"operador":"gte","valor":1,"unidad":"mm"}}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('sclerotinia','tallo',5,'Natali 14-08; SINAVIMO/SENASA','Evaluación parcial: no mide 42-72 h de mojado, canopeo, drenaje, esclerocios ni aplica aún R2-R3.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con Sclerotinia","explicacion":"Coinciden temperatura, humedad persistente y lluvia; no constituye diagnóstico.","recomendacion":"Monitorear el lote, priorizando floración y canopeos densos.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[10,28],"unidad":"C"},{"variable":"humedad_relativa","agregador":"dias_con_condicion","operador":"gte","valor":3,"unidad":"dias","subcondicion":{"operador":"gte","valor":85,"unidad":"%"}},{"variable":"precipitacion","agregador":"dias_con_condicion","operador":"gte","valor":1,"unidad":"dias","subcondicion":{"operador":"gte","valor":1,"unidad":"mm"}}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('macrophomina','raiz_tallo',14,'Natali 14-08; Crop Protection Network','Evaluación parcial: usa calor, HR baja y precipitación baja; no confirma estrés del cultivo ni inóculo.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con podredumbre carbonosa","explicacion":"Coinciden calor y ambiente seco prolongado; no constituye diagnóstico.","recomendacion":"Revisar disponibilidad de agua y monitorear sectores más secos.","condiciones":[{"variable":"temperatura_max","agregador":"dias_con_condicion","operador":"gte","valor":5,"unidad":"dias","subcondicion":{"operador":"gt","valor":30,"unidad":"C"}},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"lte","valor":45,"unidad":"%"},{"variable":"precipitacion","agregador":"suma_ventana","operador":"lt","valor":10,"unidad":"mm"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('mancha_ojo_rana','foliar',5,'Natali 14-08; University of Minnesota Extension','Evaluación parcial: no observa rocío, lluvia abundante formalizada, inóculo ni aplica aún fenología.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con mancha ojo de rana","explicacion":"Coinciden temperatura y HR mayor a 90%; no constituye diagnóstico.","recomendacion":"Monitorear hojas, especialmente desde floración.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[25,35],"unidad":"C"},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"gt","valor":90,"unidad":"%"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('tizon_bacteriano','bacteriosis',3,'Natali 14-08; University of Minnesota Extension','Experimental. No observa tormenta, granizo, lesiones ni inóculo. El viento se conserva en la serie como dato complementario, pero no condiciona la coincidencia.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Coincidencia experimental con ambiente de tizón bacteriano","explicacion":"Coinciden tiempo fresco y precipitación; no prueba tormenta, heridas ni enfermedad.","recomendacion":"Resultado interno para QA; no presentar como alerta pública estándar.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[15,20],"unidad":"C"},{"variable":"precipitacion","agregador":"suma_ventana","operador":"gt","valor":0,"unidad":"mm"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('pustula_bacteriana','bacteriosis',3,'Natali 14-08; University of Minnesota Extension','Experimental. No observa tormenta, granizo, lesiones ni inóculo. El viento se conserva en la serie como dato complementario, pero no condiciona la coincidencia.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Coincidencia experimental con ambiente de pústula bacteriana","explicacion":"Coinciden tiempo cálido y precipitación; no prueba tormenta, heridas ni enfermedad.","recomendacion":"Resultado interno para QA; no presentar como alerta pública estándar.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[25,30],"unidad":"C"},{"variable":"precipitacion","agregador":"suma_ventana","operador":"gt","valor":0,"unidad":"mm"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('oidio','foliar',5,'Natali 14-08; University of Minnesota Extension','Evaluación parcial: HR >90% proviene de la definición primaria; la fuente externa respalda tiempo fresco, no lluvia.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con oídio","explicacion":"Coinciden temperatura fresca y HR alta según la definición de Natali; no constituye diagnóstico.","recomendacion":"Monitorear hojas en etapas reproductivas.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[18,24],"unidad":"C"},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"gt","valor":90,"unidad":"%"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}'),
('mildiu','foliar',5,'Natali 14-08; University of Minnesota Extension','Evaluación parcial: no observa rocío/inóculo ni aplica aún R1-R7.','{"niveles":[{"orden":1,"clave":"condiciones_detectadas","orden_visual":1,"etiqueta":"Ambiente compatible con mildiu","explicacion":"Coinciden temperatura moderada y HR alta; no constituye diagnóstico.","recomendacion":"Monitorear hojas jóvenes, especialmente desde floración.","condiciones":[{"variable":"temperatura_media","agregador":"media_ventana","operador":"between","valor":[20,22],"unidad":"C"},{"variable":"humedad_relativa","agregador":"media_ventana","operador":"gt","valor":90,"unidad":"%"}]}],"sin_coincidencia":{"estado":"sin_condiciones"}}')
)
insert into reglas_agronomicas
  (cultivo,categoria_nombre,condicion,causas,recomendacion,regla_version,estado_regla,prioridad,activa,combinador,condiciones,clave,version,estado,ventana_dias,fuente_tecnica,limitaciones_declaradas,validado_por,validado_en,condiciones_revision,decisiones_pendientes,definicion)
select 'soja',categoria,'favorable','{}','Monitorear el lote; esta señal ambiental no constituye diagnóstico.','2.0','experimental',400,true,'all','[]',clave,'2.0',
  case when clave in ('antracnosis','sclerotinia','mancha_ojo_rana','tizon_bacteriano','pustula_bacteriana') then 'experimental' else 'vigente' end,
  ventana,fuente,limitaciones,'Fuente agronómica: Natali; normalización técnica parcial: Avizor',null,
  'Revisar al incorporar mojado foliar, fenología operativa o nueva evidencia.',array['Implementación PARCIALMENTE_EVALUABLE; no afirmar validación integral','Aplicar fenología como priorización cuando el contrato lo permita'],definicion::jsonb
from nuevas
on conflict (cultivo,clave,version) where clave is not null do update set
  categoria_nombre=excluded.categoria_nombre, estado_regla=excluded.estado_regla, estado=excluded.estado, activa=true, ventana_dias=excluded.ventana_dias,
  fuente_tecnica=excluded.fuente_tecnica, limitaciones_declaradas=excluded.limitaciones_declaradas,
  validado_por=excluded.validado_por, validado_en=excluded.validado_en, condiciones_revision=excluded.condiciones_revision,
  decisiones_pendientes=excluded.decisiones_pendientes, definicion=excluded.definicion, updated_at=now();

insert into auditoria(actor_id,actor_tipo,accion,entidad,entidad_id,valor_anterior,valor_nuevo,request_id)
select 'migration-009','service','crear_version','regla',id::text,null,
  jsonb_build_object('clave',clave,'version',version,'estado',estado,'fuente_tecnica',fuente_tecnica),gen_random_uuid()
from reglas_agronomicas where cultivo='soja' and version='2.0' and clave in
  ('antracnosis','cercospora_kikuchii','roya_asiatica','sclerotinia','macrophomina','mancha_ojo_rana','tizon_bacteriano','pustula_bacteriana','oidio','mildiu')
and not exists (
  select 1 from auditoria a where a.actor_id='migration-009' and a.accion='crear_version' and a.entidad_id=reglas_agronomicas.id::text
);
